import React, { useState, useEffect } from "react";
import { adminService } from "../services/adminService";
import { Bike, Search, MapPin } from "lucide-react";
import toast from "react-hot-toast";

const RidersDistance = () => {
  const [riders, setRiders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");

  const fetchRidersDistance = async () => {
    try {
      setLoading(true);
      const data = await adminService.getRidersDistance();
      setRiders(data);
    } catch (error) {
      console.error(error);
      toast.error("Failed to load riders distance data");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRidersDistance();
  }, []);

  const filteredRiders = riders.filter((rider) =>
    rider.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    rider.phone?.includes(searchTerm)
  );

  if (loading) {
    return (
      <div className="content-area">
        <div className="table-loader">Loading Riders Distance...</div>
      </div>
    );
  }

  return (
    <div className="content-area animate-fade-in">
      <div className="page-header">
        <div className="page-title-group">
          <h2>Riders Distance</h2>
          <span className="subtitle">
            Total distance covered by riders across Orders, Custom Orders, and Rides
          </span>
        </div>
        <div className="header-actions">
          <div className="search-bar">
            <Search size={20} />
            <input
              type="text"
              placeholder="Search riders by name or phone..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
      </div>

      <div className="table-container">
        <table className="data-table">
          <thead>
            <tr>
              <th>Rider Info</th>
              <th>Status</th>
              <th>Total Distance (km)</th>
            </tr>
          </thead>
          <tbody>
            {filteredRiders.map((rider) => (
              <tr key={rider._id}>
                <td>
                  <div className="user-info-cell">
                    <div className="user-avatar">
                      <Bike size={20} />
                    </div>
                    <div className="user-details">
                      <span className="user-name">{rider.name || "N/A"}</span>
                      <span className="user-phone">{rider.phone}</span>
                      {rider.city && (
                        <span className="user-email" style={{ display: 'flex', alignItems: 'center', gap: '4px', marginTop: '2px' }}>
                          <MapPin size={12} /> {rider.city}
                        </span>
                      )}
                    </div>
                  </div>
                </td>
                <td>
                  <span
                    className={`status-badge ${
                      rider.isVerified ? "completed" : "pending"
                    }`}
                  >
                    {rider.isVerified ? "Verified" : "Unverified"}
                  </span>
                  <span
                    className={`status-badge ${
                      rider.isOnline ? "active" : "inactive"
                    }`}
                    style={{ marginLeft: '8px' }}
                  >
                    {rider.isOnline ? "Online" : "Offline"}
                  </span>
                </td>
                <td>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <div
                      style={{
                        padding: '6px 12px',
                        background: 'rgba(59, 130, 246, 0.1)',
                        color: 'var(--accent-primary)',
                        borderRadius: '8px',
                        fontWeight: '600'
                      }}
                    >
                      {rider.totalDistance.toFixed(2)} km
                    </div>
                  </div>
                </td>
              </tr>
            ))}
            {filteredRiders.length === 0 && (
              <tr>
                <td colSpan="3" className="empty-state">
                  No riders found
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default RidersDistance;
